/**
 * Playback state type definitions
 * 
 * Defines playback state snapshot structures consumed by React components.
 */

import type { PlayMode } from "@/main";
import type { LyricLine } from "@/utils/lyrics/parser";
import type { ExtendedLyricLine } from "@/utils/lyrics/extendedParser";

/**
 * Playback snapshot interface
 * 
 * Generated by SnapshotService and supplied via usePlaybackState hook.
 */
export interface ReactPlaybackSnapshot {
	/** Active track title */
	title: string;
	/** Active track artist */
	artist: string;
	/** Active track cover URL (optional) */
	coverUrl?: string;
	/** Playback active flag */
	isPlaying: boolean;
	/** Current elapsed time in seconds */
	currentTime: number;
	/** Total track duration in seconds */
	duration: number;
	/** Play mode (order, loop, single, random) */
	playMode: PlayMode;
	/** Previous lyric line text */
	prevLyric: string;
	/** Current active lyric line text */
	currentLyric: string;
	/** Next lyric line text */
	nextLyric: string;
	/** Previous karaoke lyric line (optional) */
	prevExtendedLyric?: ExtendedLyricLine;
	/** Current active karaoke lyric line (optional) */
	currentExtendedLyric?: ExtendedLyricLine;
	/** Next karaoke lyric line (optional) */
	nextExtendedLyric?: ExtendedLyricLine;
	/** Full list of standard lyric lines */
	fullLyrics: LyricLine[];
	/** Full list of extended karaoke lyric lines */
	fullExtendedLyrics: ExtendedLyricLine[];
	/** Previous track cover URL (optional) */
	prevCoverUrl?: string;
	/** Next track cover URL (optional) */
	nextCoverUrl?: string;
	/** File path of active track */
	currentPath: string | null;
	/** Section ID of active playlist context (optional) */
	sectionId?: string | null;
	/** Current volume (0.0 - 1.0) */
	volume: number;
	/** Current playback rate (0.25 - 4.0) */
	playbackRate: number;
	/** Whether active track is marked as favorite */
	isFavorite: boolean;
}
